import sys
from collections import deque


class Node:
    __slots__ = ('val', 'neighbors')
    def __init__(self, val=0, neighbors=None):
        self.val = val
        self.neighbors = neighbors if neighbors is not None else []


def clone_brute(node):
    if node is None:
        return None
    d = {node.val: Node(node.val)}
    stack = [node]
    while stack:
        n = stack.pop()
        for nb in n.neighbors:
            if nb.val not in d:
                d[nb.val] = Node(nb.val)
                stack.append(nb)
            d[n.val].neighbors.append(d[nb.val])
    return d[node.val]


if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    idx = 0
    n = int(data[idx]); idx += 1
    nodes = {i: Node(i) for i in range(1, n + 1)}
    for _ in range(n):
        val = int(data[idx]); idx += 1
        cnt = int(data[idx]); idx += 1
        for _ in range(cnt):
            nb = int(data[idx]); idx += 1
            nodes[val].neighbors.append(nodes[nb])
    if n == 0:
        print(0)
        sys.exit(0)
    cloned = clone_brute(nodes[1])
    cmap = {}
    q = deque([cloned])
    cmap[cloned.val] = cloned
    while q:
        c = q.popleft()
        for nb in c.neighbors:
            if nb.val not in cmap:
                cmap[nb.val] = nb
                q.append(nb)
    lines = [str(n)]
    for i in range(1, n + 1):
        c = cmap[i]
        nbs = ' '.join(str(x.val) for x in c.neighbors)
        lines.append('{} {} {}'.format(c.val, len(c.neighbors), nbs) if nbs else '{} {}'.format(c.val, len(c.neighbors)))
    print('\n'.join(lines))

