import sys
from collections import deque


class Node:
    __slots__ = ('val', 'neighbors')
    def __init__(self, val=0, neighbors=None):
        self.val = val
        self.neighbors = neighbors if neighbors is not None else []


def clone_best(node):
    d = {}

    def dfs(n):
        if n.val in d:
            return d[n.val]
        c = Node(n.val)
        d[n.val] = c
        for nb in n.neighbors:
            c.neighbors.append(dfs(nb))
        return c

    return dfs(node)


